import collections

def get_manager_names(filename):
    names = {}
    with open(filename, 'r') as f:
        header = f.readline()
        for line in f:
            parts = line.strip().split('\t')
            if len(parts) >= 10:
                acc = parts[0]
                name = parts[9]
                names[acc] = name
    return names

def get_palantir_holdings(filename, names):
    cusips = {"69608A108", "69608A908", "69608A958", "67059N108", "742718109", "69608a108"}
    holdings = collections.defaultdict(int)
    with open(filename, 'r') as f:
        header = f.readline()
        for line in f:
            parts = line.strip().split('\t')
            if len(parts) >= 15:
                acc = parts[0]
                cusip = parts[4]
                value = int(parts[6])
                putcall = parts[9]
                if cusip in cusips and putcall == "":
                    name = names.get(acc, acc)
                    holdings[name] += value
    return holdings

names = get_manager_names('/root/2025-q3/COVERPAGE.tsv')
holdings = get_palantir_holdings('/root/2025-q3/INFOTABLE.tsv', names)

sorted_holdings = sorted(holdings.items(), key=lambda x: x[1], reverse=True)

for name, val in sorted_holdings[:5]:
    print(f"{name}: {val}")
